mapper.select:
SELECT id
FROM learn_task_recurrence
WHERE status = 'ACTIVE'
  AND next_generation_date <= #{businessDate}
  AND id > #{afterId}
ORDER BY id
LIMIT #{limit}

mapper.update:
UPDATE learn_task_recurrence
SET status = 'STOPPED',
    stopped_by_user_id = #{stoppedByUserId},
    stopped_at = #{stoppedAt},
    version_no = version_no + 1,
    updated_at = #{stoppedAt}
WHERE id = #{id}
  AND status = 'ACTIVE'
  AND version_no = #{expectedVersion}
